"""Compile topology bindings for the v5/v6 source-driven network pipelines.

These are input records, never surface vertices or precomputed bend samples.
Coordinates, widths, offsets, mouth trims and grass boundaries evaluate in GN.
"""
import math
import time
import bpy
from mathutils import Matrix, Vector
