def _junctions(net, *, allow_free=False):
    old, _ = runtime.solver_modules()
    sections = {s.id: s for s in net.canonical.sections}
    owners = net.canonical.section_streets()
    datums = {round(j.datum, 7) for j in net.intersection_records.values()}
    if len(datums) != 1 and not (allow_free and not datums):
        raise ValueError('Editable paths currently require one common flat datum')
    attached, ends, result = {}, {}, []
    for j in net.intersection_records.values():
        connectors = [c for c in net.connector_records.values() if c.intersection_id == j.id]
        def angle(c):
            sid, end = c.members[0]; p = sections[sid].vertices
            a, b = (p[0], p[1]) if end == 0 else (p[-1], p[-2])
            return math.atan2(b[1]-a[1], b[0]-a[0]) % math.tau
        connectors.sort(key=angle)
        streets, inputs, profiles = [], [], []
        for i, c in enumerate(connectors):
            if len(c.members) not in (1, 2):
                raise ValueError('A Connector needs one carriageway or a two-member Bundle')
            members = []
            reference = net.section_records[c.members[0][0]]
            rise, preset = (c.rise, c.preset) if c.use_profile_override else (reference.rise, reference.preset)
            for k, (sid, end) in enumerate(c.members):
                section = sections[sid]; profile = net.section_records[sid]
                if (sid, end) in attached:
                    raise ValueError('A Section end has two intersection owners')
                if abs(profile.rise-rise) > 1.e-7 or profile.preset != preset:
                    raise ValueError('A carriageway must retain the same profile along its entire path')
                attached[sid, end] = j.id; ends[j.id, sid] = end
                points = section.vertices[:2] if end == 0 else section.vertices[-2:]
                member_index = len(streets)
                streets.append(old.StreetInput(owners[sid], (old.SectionInput(sid, points, section.width, section.offset),)))
                members.append(old.MemberInput(member_index, end == 0, c.lateral_orders[k],
                    0 if c.bundle_id != -1 else -1))
            profiles.append(old.ProfileInput(rise, old.FLAT if preset == 'FLAT' else old.SMOOTH_CROWN, c.separator))
            radius = c.radius_override if c.radius_override > 0 else j.radius
            if c.radius_override > 0 and c.radius_next_connector_id != connectors[(i+1) % len(connectors)].id:
                raise ValueError('Corner override no longer identifies an adjacent connector pair')
            inputs.append(old.ConnectorInput(c.id, tuple(members), i, radius=radius,
                item_kind=old.BUNDLE_ITEM if c.bundle_id != -1 else old.STREET_ITEM,
                bundle_source_id=c.bundle_id))
        junction = old.PreparedJunction(j.id, j.position, tuple(streets), tuple(inputs), tuple(profiles), j.datum, net.cell_size)
        old.validate_initial_scope(junction); result.append(junction)
    if not result and not allow_free:
        raise ValueError('An editable network needs intersections')
    return tuple(result), ends, attached


def _pairs(net, *, allow_free=False):
    """Declare partner and directed inner side from authored Bundle topology."""
    sections = {s.id: s for s in net.canonical.sections}
    streets = {s.id: s for s in net.canonical.streets}
    result = {}
    sweep_plan = bundle_chains.plan(net)
    aggregate = {c.bundle_id: [] for c in sweep_plan.chains if c.aggregate}
    for chain in sweep_plan.chains:
        if chain.aggregate:
            aggregate[chain.bundle_id].append(chain)
    for bundle in net.bundle_records.values():
        if len(bundle.members) != 2:
            raise ValueError('Editable separators currently require two Bundle members')
        if bundle.id in aggregate:
            for chain in aggregate[bundle.id]:
                partner = sweep_plan.chains[chain.partner]
                reference = net.section_records[partner.sections[0][0]]
                for sid, forward in chain.sections:
                    profile = net.section_records[sid]
                    if profile.preset != reference.preset or abs(profile.rise-reference.rise) > 1e-7:
                        raise ValueError('Paired carriageways require one shared profile and rise')
                    result[sid] = (partner.sections[0][0], chain.reversed_pair,
                                  chain.inner_u if forward else 1.-chain.inner_u,
                                  chain.owner, bundle.id)
            continue
        specs = []
        for street_id, forward, _head, _tail in bundle.members:
            items = streets[street_id].sections
            if len(items) != 1:
                raise ValueError('Divided editable paths currently require one complete Section per member Street')
            sid, section_forward = items[0]
            specs.append((sid, section_forward == forward))
        a, af = specs[0]; b, bf = specs[1]
        if a == b:
            raise ValueError(f'Bundle {bundle.id} must reference two distinct member Streets')
        repeated = [sid for sid in (a, b) if sid in result]
        if repeated:
            raise ValueError(f'Section {repeated[0]} belongs to multiple whole-Street Bundles; '
                             'partial Bundle membership extents are not supported by this backend')
        if abs(net.section_records[a].rise-net.section_records[b].rise) > 1.e-7:
            raise ValueError('Paired carriageways require a shared crown rise')
        if net.section_records[a].preset != net.section_records[b].preset:
            raise ValueError('Paired carriageways require one shared profile preset')
        sides = {}
        for c in net.connector_records.values():
            if c.bundle_id != bundle.id:
                continue
            lateral = []
            sid0, end0 = c.members[0]; p0 = sections[sid0].vertices
            origin = Vector(p0[0] if end0 == 0 else p0[-1])
            tangent = (Vector(p0[1] if end0 == 0 else p0[-2])-origin).normalized()
            right = Vector((tangent.y, -tangent.x, 0.))
            for sid, end in c.members:
                section = sections[sid]; endpoint = Vector(section.vertices[0] if end == 0 else section.vertices[-1])
                lateral.append(((endpoint-origin).dot(right)+section.offset*(1 if end == 0 else -1), sid, end))
            for rank, (_at, sid, end) in enumerate(sorted(lateral)):
                inner = float((rank == 0) != (end == 1))
                if sid in sides and sides[sid] != inner:
                    raise ValueError('The Bundle inner side disagrees between its two mouths')
                sides[sid] = inner
        if set(sides) != {a, b}:
            if not allow_free:
                raise ValueError('A divided path needs an attached shared-profile mouth to define its inner side')
            # A free Bundle has explicit membership and lateral order, but no
            # artificial intersection is needed just to encode its inner sides.
            for member, (sid, forward) in zip(bundle.members, specs):
                if member[2] != member[3]:
                    raise ValueError('Bundle centerlines cannot exchange lateral order')
                inner = float((member[2] == 0) == forward)
                if sid in sides and sides[sid] != inner:
                    raise ValueError('Bundle order disagrees with its attached mouth')
                sides[sid] = inner
        for sid, partner in ((a, b), (b, a)):
            result[sid] = (partner, af != bf, sides[sid], sid == a, bundle.id)
    return result


def _path_object(controller, net, sections, seams, attached):
    from . import transition_bindings
    transitions = transition_bindings.endpoints(net)
    name = 'Prochitecture Streets / Path records / '+controller.st_network.network_uuid
    obj = bpy.data.objects.get(name)
    mesh = bpy.data.meshes.new(name+' data')
    ordered = sorted(net.section_records); rows = {sid: i for i, sid in enumerate(ordered)}
    mesh.from_pydata([(0., 0., 0.)]*len(ordered), [], [])
    datum = next(iter(net.intersection_records.values())).datum if net.intersection_records else 0.
    pairs = _pairs(net, allow_free=bool(controller.get('st_network_v8', False)))
    sweep_plan = bundle_chains.plan(net)
    bindings = sweep_plan.section_bindings()
    chain_fields = sweep_plan.path_fields(pairs)
    endpoint_section = {v: sid for sid, (vp, _ep) in sections.items() for v in (vp[0], vp[-1])}
    values = []
    for sid in ordered:
        vp, ep = sections[sid]
        partner, reversed_pair, inner, grass, bundle = pairs.get(sid, (sid, False, 0., False, -1))
        row = dict(st_path_id=sid, st_path_start=vp[0], st_path_count=len(vp), st_path_edge=ep[0],
            st_path_attached_start=(sid, 0) in attached, st_path_attached_end=(sid, 1) in attached,
            st_path_rise=net.section_records[sid].rise, st_path_datum=datum,
            st_path_clip_start=net.section_records[sid].clip_start,
            st_path_clip_end=net.section_records[sid].clip_end,
            st_path_divided=sid in pairs, st_path_partner=rows[partner],
            st_path_partner_reversed=reversed_pair, st_path_inner_u=inner,
            st_path_make_grass=grass, st_path_bundle_id=bundle)
        row.update(chain_fields[sid])
        for end, key in [('start', vp[0]), ('end', vp[-1])]:
            transition = transitions.get((sid, int(end == 'end')))
            base = 'st_path_'+end+'_transition'
            row[base] = transition.id if transition else -1
            row[base+'_half'] = transition.minimum_half_length if transition else 0.
            row[base+'_slope'] = transition.maximum_edge_slope if transition else .3
            seam = seams.get(key)
            prefix = 'st_path_'+end+'_seam'
            row[prefix] = seam[0] if seam else -1
            row[prefix+'_neighbor'] = seam[1] if seam else -1
            row[prefix+'_edge'] = seam[3] if seam else -1
            row[prefix+'_sign'] = float(seam[5]) if seam else 1.
            row[prefix+'_rise'] = net.section_records[endpoint_section[seam[0]]].rise if seam else row['st_path_rise']
            row[base+'_partner'] = bindings[endpoint_section[seam[0]]][0].index if transition and seam else -1
        values.append(row)
    for key in values[0]:
        value = values[0][key]
        kind = 'BOOLEAN' if isinstance(value, bool) else 'FLOAT' if isinstance(value, float) else 'INT'
        path_runtime._attribute(mesh, key, kind, [v[key] for v in values])
    if obj is None:
        obj = bpy.data.objects.new(name, mesh); bpy.context.scene.collection.objects.link(obj)
    else:
        previous = obj.data; obj.data = mesh
        if previous.users == 0:
            bpy.data.meshes.remove(previous)
    obj.matrix_world = Matrix.Identity(4); obj.hide_render = True; obj.hide_select = True; obj.hide_set(True)
    obj.st_generated_controller = controller
    return obj


def refresh(controller, *, force=False, raise_errors=False):
    started = time.perf_counter()
    dynamic_bundles = bool(controller.get('st_network_v8', False))
    local_diagnostics = dynamic_bundles or bool(controller.get('st_network_v7', False))
    if local_diagnostics:
        from . import local_network_nodes as network_nodes
    elif controller.get('st_network_v6', False):
        from . import centerline_network_nodes as network_nodes
    else:
        from . import unified_network_nodes as network_nodes
    if runtime._busy:
        return False
    previous_modifier = next((m for m in controller.modifiers if m.type == 'NODES'), None)
    visible = previous_modifier.show_viewport if previous_modifier else True
    def signature_of(net):
        return (net.signature, tuple((sid, s.object.as_pointer(), s.object.data.as_pointer(), s.vertex_indices, s.edge_indices)
                for sid, s in sorted(net.section_sources.items())),
                tuple((obj.as_pointer(), tuple(v for row in obj.matrix_basis for v in row))
                      for obj in (controller, *net.sources)))
    try:
        with runtime.suspend():
            key = controller.as_pointer()
            # A cache hit must be read-only. Toggling show_viewport before this
            # check dirtied the GN output even when nothing had changed.
            if not force and key in runtime._last:
                net = model.read_network(controller)
                if runtime._last[key] == signature_of(net):
                    return False
            # Managed topology edits invalidate old source lookup indices. Do
            # not evaluate the old graph until the complete binding is replaced.
            if previous_modifier:
                previous_modifier.show_viewport = False
            # Deferred metadata edits can run while the source is in Edit
            # Mode. Flush its BMesh before rebinding so GN does not retain the
            # last object-mode copy during recovery from an invalid input.
            for source in model._sources(controller):
                if source.mode == 'EDIT':
                    source.update_from_editmode()
            bpy.context.view_layer.update(); net = model.read_network(controller)
            normalized = time.perf_counter()
            signature = signature_of(net)
            junctions, ends, attached = _junctions(net, allow_free=dynamic_bundles)
            source_collection, sections, seams, nv, ne = live_bindings.compile_sources(controller, net)
            collection = runtime._cache_collection(controller)
            carriers = tuple(runtime._carrier(controller, j, collection) for j in junctions)
            for obj, j in zip(carriers, junctions):
                path_runtime._bind_rays(obj.data, j, sections, ends)
                bindings = bundle_chains.plan(net).section_bindings()
                records = obj.data.attributes['s2_record_type']
                member_indices = [i for i, row in enumerate(records.data) if row.value == 5]
                start_keys, end_keys = [-1]*len(records.data), [-1]*len(records.data)
                for at, street in zip(member_indices, j.streets):
                    sid = street.sections[0].source_id
                    chain, _rank, forward = bindings[sid]
                    if not chain.aggregate:
                        continue
                    first_sid, first_forward = chain.sections[0]
                    last_sid, last_forward = chain.sections[-1]
                    first = sections[first_sid][0][0 if first_forward else -1]
                    last = sections[last_sid][0][-1 if last_forward else 0]
                    # Keys follow this terminal Section's authored direction;
                    # the native ray group selects outward order at either end.
                    start_keys[at], end_keys[at] = (first, last) if forward else (last, first)
                for name, values in (('st_bundle_chain_start', start_keys), ('st_bundle_chain_end', end_keys)):
                    live_bindings.attribute(obj.data, name, 'POINT', values)
            runtime._synchronize_carriers(controller, collection, carriers)
            paths = _path_object(controller, net, sections, seams, attached)
            # Reuse the saved shared graph before evaluating the builder's
            # arguments. The old unused wrapper kernel can be absent after
            # reopening; rebuilding it recreates helpers used by every output.
            network_name = network_nodes.NAME_V8 if dynamic_bundles else network_nodes.NAME
            group = controller.st_network.solver_group or bpy.data.node_groups.get(network_name)
            if group is None:
                if dynamic_bundles:
                    if 'Street Blosm / Prepare Section geometry v1' not in bpy.data.node_groups:
                        runtime.ensure_kernel()
                    group = network_nodes.build(None, dynamic_bundles=True)
                else:
                    group = network_nodes.build(runtime.ensure_kernel())
            mod = next((m for m in controller.modifiers if m.type == 'NODES'), None) or controller.modifiers.new('Editable Street network', 'NODES')
            mod.node_group = group
            controls = {'Source Objects': source_collection, 'Source Vertex Count': nv, 'Source Edge Count': ne,
                'Junction Inputs': collection, 'Path Inputs': paths, 'Cell Size': net.cell_size,
                'Metres to Blender Units': 1/net.scale_length, 'Mesh Resolution': controller.st_network.resolution,
                'Height Exaggeration': controller.st_network.exaggeration, 'Enabled': True}
            for material in ('Pavement', 'Grass'):
                mat = getattr(controller.st_network, material.lower()+'_material', None) or bpy.data.materials.get('Prochitecture Streets / '+material)
                if mat:
                    controls[material] = mat
            for name, value in controls.items():
                runtime._set_modifier(controller, name, value)
            mod.show_viewport = visible
            # This is an explicit managed refresh, never an idle viewport poll.
            # Read native diagnostic codes even if their display is hidden;
            # hiding warnings must not change validity or disable live recovery.
            restore_diagnostics = False
            if local_diagnostics:
                diagnostic_socket = next(s for s in group.interface.items_tree
                    if s.item_type == 'SOCKET' and s.in_out == 'INPUT' and s.name == 'Show Diagnostics')
                displayed = (getattr(mod.properties.inputs, diagnostic_socket.identifier).value
                    if hasattr(mod, 'properties') else mod[diagnostic_socket.identifier])
                if not displayed:
                    runtime._set_modifier(controller, 'Show Diagnostics', True)
                    restore_diagnostics = True
            bound = time.perf_counter()
            controller.update_tag(); bpy.context.view_layer.update()
            ev = controller.evaluated_get(bpy.context.evaluated_depsgraph_get()); mesh = ev.to_mesh()
            native_diagnostics = []
            try:
                if not mesh.polygons and not local_diagnostics:
                    raise ValueError('GN rejected editable network: check mouth lengths, paired tangents, bends, widths, separator gap and Section seams')
                if local_diagnostics:
                    codes = mesh.attributes.get('st_diagnostic_code')
                    if codes:
                        native_diagnostics = sorted({v.value for v in codes.data if v.value})
                    if not mesh.polygons:
                        native_diagnostics = [30]
            finally:
                ev.to_mesh_clear()
                if restore_diagnostics:
                    runtime._set_modifier(controller, 'Show Diagnostics', False)
            runtime._metrics[controller.name] = {
                'source_validation_seconds': normalized-started,
                'binding_seconds': bound-normalized,
                'evaluation_and_diagnostics_seconds': time.perf_counter()-bound,
                'refresh_and_evaluation_seconds': time.perf_counter()-started,
                'junctions': len(junctions), 'sections': len(net.canonical.sections)}
            runtime._last[key] = signature
            message = ('One native pipeline: exact or interpolating carriageways, rounded intersections and paired separator grass'
                       if controller.get('st_network_v7', False) or controller.get('st_network_v6', False) else
                       'One native pipeline: editable carriageways, rounded intersections and paired separator grass')
            if dynamic_bundles:
                message = 'Shared native solver: live carriageways, dynamic Bundle profiles, pavement unions and separator islands'
            if native_diagnostics:
                runtime._set_status(controller, 'INVALID', 'Some geometry was rejected; see the native red diagnostic labels. Codes: '+', '.join(map(str, native_diagnostics)))
            else:
                runtime._set_status(controller, 'READY', message)
            return True
    except Exception as exc:
        runtime._last.pop(controller.as_pointer(), None)
        failed_modifier = next((m for m in controller.modifiers if m.type == 'NODES'), None)
        if failed_modifier and failed_modifier.node_group:
            runtime._set_modifier(controller, 'Enabled', False)
        if previous_modifier:
            previous_modifier.show_viewport = visible
        runtime._set_status(controller, 'INVALID', str(exc))
        if raise_errors:
            raise
        return False
